@if(session('success') || session('error'))<div class="pointer-events-none fixed right-4 top-20 z-[60] w-[calc(100%-2rem)] max-w-sm" x-data="{show:true}" x-init="setTimeout(()=>show=false,5000)" x-show="show" x-transition><div class="pointer-events-auto relative"><x-alert :type="session('success') ? 'success' : 'error'">{{ session('success') ?? session('error') }}</x-alert><button @click="show=false" class="absolute right-2 top-2 rounded p-1 opacity-60 hover:opacity-100" aria-label="Đóng thông báo">×</button></div></div>@endif
